css:
.print-format {
  font-family: 'Helvetica Neue', Arial, sans-serif;
  padding: 20px;
}
.print-format .header {
  text-align: center;
  border-bottom: 3px solid #1abc9c;
  padding-bottom: 10px;
  margin-bottom: 20px;
}
.print-format .header h1 {
  color: #1abc9c;
  font-size: 22px;
  margin: 0;
}
.print-format .header h3 {
  color: #555;
  font-size: 14px;
  margin: 5px 0 0 0;
  font-weight: normal;
}
.print-format .section-title {
  background: #1abc9c;
  color: white;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: bold;
  margin: 15px 0 8px 0;
}
.print-format table {
  width: 100%;
  border-collapse: collapse;
  margin: 8px 0;
}
.print-format table th {
  background: #f0f0f0;
  padding: 6px 8px;
  text-align: left;
  font-size: 11px;
  border: 1px solid #ddd;
}
.print-format table td {
  padding: 6px 8px;
  font-size: 11px;
  border: 1px solid #ddd;
}
.print-format .footer {
  margin-top: 30px;
  padding-top: 10px;
  border-top: 1px solid #ddd;
  font-size: 10px;
  color: #888;
  text-align: center;
}
.print-format .seal-area {
  margin-top: 20px;
  text-align: right;
}
.print-format .grade-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 4px;
  font-weight: bold;
  font-size: 16px;
}
